def modularity(graph, partition):
    q = nx.graph_clustering(graph)
    m = len(graph.edges)
    modularity_score = 0.0
    for community in partition:
        for node1, node2 in zip(community, community[1:]):
            if graph.has_edge(node1, node2):
                modularity_score += q[node1] * q[node2] / m
        modularity_score -= sum(q[node] ** 2 for node in community) / 2.0
    return modularity_score

def normalized_cut(graph, partition):
    cut = sum(sum(1 for edge in graph.edges() if graph.nodes()[edge][0] in partition[0] and graph.nodes()[edge][1] in partition[1]))
    return cut / graph.number_of_edges()

def balance_constraint(graph, partition):
    sizes = {partition[i]: 0 for i in range(2)}
    for node in graph.nodes():
        sizes[partition[node]] += 1
    return np.sum([abs(sizes[partition[i]] - len(graph.nodes()) // 2) for i in range(2)])

def approximation_ratio_(partition, known_reference_partition):
    return 1.0 - (len(set(partition).intersection(set(known_reference_partition))) / len(partition))
